// CLEANING : retire couverture, introduction et mentions parasites ; garde les 100 titres (table des matières) et le corps du livre
// À ADAPTER au PDF utilisé :
//  - PIED_DE_PAGE : texte (ou fragment) du pied de page répété dans le PDF. Il marque la fin de la table des matières,
//    de l'introduction et de la couverture ; la dernière occurrence marque le début du corps du livre.
//  - LIGNES_A_RETIRER : expressions régulières des lignes parasites à supprimer du corps (mentions d'éditeur, de remerciement...).
const PIED_DE_PAGE = 'A-ADAPTER-pied-de-page-repete-dans-le-PDF';
const LIGNES_A_RETIRER = [/^A-ADAPTER-ligne-parasite$/i];

const brut = $input.first().json.text;
const texte = (Array.isArray(brut) ? brut.join('\n') : String(brut || '')).replace(/\r\n?/g, '\n');
const lignes = texte.split('\n').map(l => l.trim());
const estPied = l => l.toLowerCase().includes(PIED_DE_PAGE.toLowerCase());

const debutTdm = lignes.findIndex(l => /^Table des mati[eè]res$/i.test(l));
if (debutTdm < 0) throw new Error('Table des matières introuvable : ce fichier est-il bien le livre attendu ?');
const finTdm = lignes.findIndex((l, i) => i > debutTdm && estPied(l));
const dernierPied = lignes.map(estPied).lastIndexOf(true);
if (finTdm < 0 || dernierPied <= finTdm) throw new Error('Fin de la table des matières introuvable');

const titres = [];
for (const l of lignes.slice(debutTdm + 1, finTdm)) {
  if (!l) continue;
  if (l.startsWith('«')) titres.push(l);
  else if (titres.length) titres[titres.length - 1] += ' ' + l;
}
if (titres.length !== 100) throw new Error('Attendu : 100 titres, trouvé : ' + titres.length);

const net = s => s.replace(/\s+/g, ' ').replace(/\s+»/g, ' »').trim();
const corps = lignes.slice(dernierPied + 1)
  .filter(l => !LIGNES_A_RETIRER.some(re => re.test(l)))
  .join('\n').trim();

return [{ json: { titres: titres.map(net), corps } }];

// CHUNKING : une sortie par citation, avec philosophe, dates, numéro et paragraphes du commentaire
const { titres, corps } = $input.first().json;

// Repérage des titres dans le corps, en ignorant les retours à la ligne
const compact = []; const idx = [];
for (let i = 0; i < corps.length; i++) if (!/\s/.test(corps[i])) { compact.push(corps[i]); idx.push(i); }
const flux = compact.join('');
let curseur = 0; const pos = [];
titres.forEach((t, i) => {
  const tc = t.replace(/\s+/g, '');
  const p = flux.indexOf(tc, curseur);
  if (p < 0) throw new Error('Titre introuvable n°' + (i + 1) + ' : ' + t);
  pos.push({ debut: idx[p], fin: idx[p + tc.length - 1] + 1 });
  curseur = p + tc.length;
});

// Largeur typique d'une ligne : sert à détecter les fins de paragraphe (ligne courte finissant par une ponctuation)
const longueurs = corps.split('\n').map(l => l.length).sort((a, b) => a - b);
const largeur = longueurs[Math.floor(longueurs.length * 0.9)];
const recolle = lignes => lignes.reduce((s, l) => s.endsWith('-') ? s + l : (s ? s + ' ' + l : l), '');

return titres.map((titre, i) => {
  const segment = corps.slice(pos[i].fin, i + 1 < titres.length ? pos[i + 1].debut : corps.length);
  const ls = segment.split('\n').map(l => l.trim()).filter(Boolean);
  let a = 0; let auteur = ls[a++];
  while (auteur.includes('(') && !/\)\s*$/.test(auteur) && a < 3 && a < ls.length) auteur += ' ' + ls[a++];
  const m = /^(.*?)\s*\(([^()]*)\)\s*$/.exec(auteur);
  const paragraphes = []; let courant = [];
  for (const l of ls.slice(a)) {
    courant.push(l);
    if (/[.!?»)…:]$/.test(l) && l.length < largeur * 0.8) { paragraphes.push(recolle(courant)); courant = []; }
  }
  if (courant.length) paragraphes.push(recolle(courant));
  return { json: { numero: i + 1, citation: titre, philosophe: m ? m[1].trim() : auteur, dates: m ? m[2].trim() : '', paragraphes } };
});

// AUGMENTATION : fusionne l'enrichissement Gemini et les métadonnées, puis produit un item par chunk (un paragraphe = un chunk)
const sources = $('Chunking').all();
const enrichis = $input.all();
if (enrichis.length !== sources.length) throw new Error('Enrichissement incomplet : ' + enrichis.length + ' réponses pour ' + sources.length + ' citations');

const sortie = [];
enrichis.forEach((e, i) => {
  const src = sources[i].json;
  let enr = e.json.output ?? e.json.text ?? e.json;
  if (typeof enr === 'string') enr = JSON.parse(enr);
  if (!enr || !enr.resume || !Array.isArray(enr.mots_cles) || !Array.isArray(enr.questions) || !enr.epoque) {
    throw new Error('Enrichissement invalide pour la citation n°' + src.numero);
  }
  src.paragraphes.forEach((p, k) => {
    const texte = [
      'Philosophe : ' + src.philosophe + (src.dates ? ' (' + src.dates + ')' : ''),
      'Citation n°' + src.numero + ' : ' + src.citation,
      '',
      p,
      '',
      'Résumé : ' + enr.resume,
      'Mots-clés : ' + enr.mots_cles.join(', '),
      'Questions types : ' + enr.questions.join(' | ')
    ].join('\n');
    sortie.push({ json: { texte, numero: src.numero, citation: src.citation, philosophe: src.philosophe, dates: src.dates, epoque: enr.epoque, paragraphe: k + 1 } });
  });
});
return sortie;

// FILTRAGE par métadonnées, après la recherche (le Simple Vector Store n'a pas de filtre natif)
const sel = $('Sélection').first().json.output;
const brut = $input.all().map(i => i.json).filter(j => j.document && j.document.pageContent);
if (!brut.length) return [{ json: { vide: true } }];

const norm = s => String(s || '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
let retenus = brut;
if (!sel.plusieurs_philosophes && (sel.philosophe || sel.epoque)) {
  const f = brut.filter(j => {
    const m = j.document.metadata || {};
    return (!sel.philosophe || norm(m.philosophe).includes(norm(sel.philosophe))) && (!sel.epoque || norm(m.epoque) === norm(sel.epoque));
  });
  if (f.length) retenus = f; // si le filtre ne laisse rien, on garde tout
}

// Aperçu léger pour le reranking : en-tête + résumé + mots-clés (le texte complet reste pour la génération)
const apercu = t => { const l = t.split('\n'); return [l[0], l[1], ...l.filter(x => /^(Résumé|Mots-clés) :/.test(x))].join('\n'); };

const chunks = retenus.slice(0, 15).map((j, i) => ({
  id: i + 1,
  texte: j.document.pageContent,
  apercu: apercu(j.document.pageContent),
  numero: j.document.metadata.numero,
  philosophe: j.document.metadata.philosophe,
  citation: j.document.metadata.citation
}));
return [{ json: { vide: false, question: sel.requete, questionOriginale: $('When chat message received').first().json.chatInput, filtre: { philosophe: sel.philosophe, epoque: sel.epoque }, chunks } }];

// RERANKING (suite) : associe les notes de Gemini aux passages, garde les 5 meilleurs au-dessus du seuil
// Question comparative : on garantit aussi le meilleur passage (score ≥ 4) de chaque philosophe cité
const { chunks, questionOriginale } = $('Filtrage').first().json;
const sel = $('Sélection').first().json.output;
const scores = ($input.first().json.output || {}).scores || [];
const note = new Map(scores.map(s => [Number(s.id), Number(s.score)]));
const SEUIL = 6;
const norm = s => String(s || '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();

const classes = chunks.map(c => ({ ...c, score: note.get(c.id) ?? 0 })).sort((a, b) => b.score - a.score);
const retenus = classes.filter(c => c.score >= SEUIL).slice(0, 5);

const noms = sel.philosophes || [];
if (noms.length > 1) {
  for (const nom of noms) {
    if (!retenus.some(c => norm(c.philosophe).includes(norm(nom)))) {
      const meilleur = classes.find(c => norm(c.philosophe).includes(norm(nom)) && c.score >= 4);
      if (meilleur) retenus.push(meilleur);
    }
  }
}

return [{ json: {
  refus: retenus.length === 0,
  questionOriginale,
  meilleurScore: classes.length ? classes[0].score : 0,
  retenus: retenus.map(c => ({ numero: c.numero, philosophe: c.philosophe, score: c.score })),
  contexte: retenus.map(c => c.texte).join('\n\n---\n\n')
} }];
